INSERT OR IGNORE INTO corpus_entries(id,source_id,type,verification,published,theme,publisher,search_text,data,original,original_hash,origin,created,updated) VALUES('flux-touristiques-01','flux-src-touristiques-01','case','partial','2023-06-19','flux 原生例句 过度旅游 tourisme durable 旅游与环境','tf1 info / afp','为了遏制这一现象(过度旅游),法国政府于6月18日公布了一项计划,旨在更好地调控和疏导旅游客流。 afin de contenir ce phenomene, l''executif a devoile, dimanche 18 juin, un plan pour mieux reguler et repartir ces flux touristiques. flux touristiques · reguler et repartir les flux touristiques flux 原生例句 过度旅游 tourisme durable 旅游与环境 tf1 info / afp','{"id":"flux-touristiques-01","type":"case","title":"flux touristiques · réguler et répartir les flux touristiques","zh":"为了遏制这一现象（过度旅游），法国政府于6月18日公布了一项计划，旨在更好地调控和疏导旅游客流。","fr":"Afin de contenir ce phénomène, l’exécutif a dévoilé, dimanche 18 juin, un plan pour mieux réguler et répartir ces flux touristiques.","source":"TF1 Info / AFP","date":"2023-06-19","url":"https://www.tf1info.fr/politique/reguler-sans-repousser-le-defi-du-gouvernement-pour-lutter-contre-le-probleme-du-surtourisme-surfrequentation-sites-touristiques-2260922.html","relation":"法语原生例句 + 中文教学译文","zhLabel":"中文教学译文（非官方平行原文）","verification":"partial","theme":"flux 原生例句 过度旅游 tourisme durable","domain":"旅游与环境","sourceId":"flux-src-touristiques-01","locator":"文章开头导语摘要第三项","verificationNote":"法语原句已与原发布页核对。 中文为此前课堂检索中的AI辅助译文，未作教师终审，不属于已核验官方双语平行句。ce phénomène 指 surfréquentation / surtourisme；中文括注为语境说明。","task":"观察搭配「réguler et répartir les flux touristiques」，结合语境比较法汉表达；联系高级法语综合课 U3 及新闻编译相关领域。","note":"关键词：flux touristiques（旅游客流）；目标搭配：réguler et répartir les flux touristiques。","keyword":"flux touristiques","gloss":"旅游客流","collocations":["réguler et répartir les flux touristiques"],"sourceLevel":"primary","translationStatus":"AI-assisted · teacher review pending","provenance":"Exo U3 跨课程共享 · flux 原生例句首批 · 2026-11-26","permission":"公开来源的必要短句及链接；仅作教学引用，不镜像全文，不推定开放授权。","datePrecision":"day","checkedAt":"2026-11-26","veri